program='''def transform(grid):
    occupied = {(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 8}
    placements = []
    max_r = len(grid) - 1
    max_c = len(grid[0]) - 1
    for r in range(max_r):
        for c in range(max_c):
            box = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if box <= occupied:
                placements.append((box, 1))
            for missing in box:
                piece = box - {missing}
                if piece <= occupied:
                    pattern = tuple(sorted((rr - r, cc - c) for rr, cc in piece))
                    colors = {
                        ((0, 0), (0, 1), (1, 1)): 3,
                        ((0, 1), (1, 0), (1, 1)): 2,
                        ((0, 0), (1, 0), (1, 1)): 4,
                        ((0, 0), (0, 1), (1, 0)): 5,
                    }
                    placements.append((piece, colors[pattern]))

    by_cell = {cell: [] for cell in occupied}
    for piece, color in placements:
        for cell in piece:
            by_cell[cell].append((piece, color))

    def solve(remaining):
        if not remaining:
            return []
        cell = min(remaining)
        for piece, color in by_cell[cell]:
            if piece <= remaining:
                rest = solve(remaining - piece)
                if rest is not None:
                    return [(piece, color)] + rest
        return None

    solution = solve(occupied)
    result = [[0 for _ in row] for row in grid]
    for piece, color in solution:
        for r, c in piece:
            result[r][c] = color
    return result
'''
